# Retrieve the input parameters directly from the globally injected 'input_data' dictionary
import json
import sys

map_id = input_data.get('map_id')
start_x = int(input_data.get('start_x'))
start_y = int(input_data.get('start_y'))
start_z = int(input_data.get('start_z'))
target_x = int(input_data.get('target_x'))
target_y = int(input_data.get('target_y'))
target_z = int(input_data.get('target_z'))

def is_plateau_tile(x, y, m_id):
    if m_id == '0_219': # West (Area 3)
        if (5 <= x <= 11) and (16 <= y <= 18):
            return True
        if (11 <= x <= 16) and (6 <= y <= 18):
            if (11 <= x <= 14) and (13 <= y <= 15):
                return False
            if x == 11 and (9 <= y <= 13):
                return False
            if x == 14 and (10 <= y <= 13):
                return False
            if x == 13 and (10 <= y <= 11):
                return False
            return True
        if (17 <= x <= 22) and (14 <= y <= 16):
            return True
    elif m_id == '0_217': # East (Area 1)
        if (12 <= x <= 22) and (13 <= y <= 20):
            return True
        if (12 <= x <= 18) and (4 <= y <= 6):
            return True
        if (19 <= x <= 29) and (12 <= y <= 12):
            return True
    elif m_id == '0_218': # North (Area 2)
        if (20 <= x <= 24) and (20 <= y <= 22):
            return True
        if (26 <= x <= 34) and (25 <= y <= 27):
            return True
    return False

def get_neighbors(cx, cy, cz):
    neighbors = []
    moves = [(0, 1, 'Down'), (0, -1, 'Up'), (-1, 0, 'Left'), (1, 0, 'Right')]

    if map_id == '0_219': # West (Area 3)
        if cz == 0 and cx == 21 and cy == 18:
            neighbors.append((21, 17, 0, 'Up'))
        elif cz == 0 and cx == 21 and cy == 17:
            neighbors.append((21, 16, 1, 'Up'))
            neighbors.append((21, 18, 0, 'Down'))
        elif cz == 1 and cx == 21 and cy == 16:
            neighbors.append((21, 17, 0, 'Down'))
        elif cz == 1 and cx == 6 and cy == 18:
            neighbors.append((6, 19, 1, 'Down'))
        elif cz == 1 and cx == 6 and cy == 19:
            neighbors.append((6, 20, 0, 'Down'))
            neighbors.append((6, 18, 1, 'Up'))
        elif cz == 0 and cx == 6 and cy == 20:
            neighbors.append((6, 19, 1, 'Up'))

    elif map_id == '0_217': # East (Area 1)
        if cz == 0 and cx == 20 and cy == 21:
            neighbors.append((20, 20, 1, 'Up'))
        elif cz == 1 and cx == 20 and cy == 20:
            neighbors.append((20, 21, 0, 'Down'))
        if cz == 1 and cx == 12 and cy == 20:
            neighbors.append((12, 21, 0, 'Down'))
        elif cz == 0 and cx == 12 and cy == 21:
            neighbors.append((12, 20, 1, 'Up'))
        if cz == 0 and cx == 12 and cy == 7:
            neighbors.append((12, 6, 1, 'Up'))
        elif cz == 1 and cx == 12 and cy == 6:
            neighbors.append((12, 7, 0, 'Down'))
        if cz == 0 and cx == 17 and cy == 7:
            neighbors.append((17, 6, 1, 'Up'))
        elif cz == 1 and cx == 17 and cy == 6:
            neighbors.append((17, 7, 0, 'Down'))

    elif map_id == '0_218': # North (Area 2)
        if cz == 0 and cx == 22 and cy == 23:
            neighbors.append((22, 22, 1, 'Up'))
        elif cz == 1 and cx == 22 and cy == 22:
            neighbors.append((22, 23, 0, 'Down'))
        if cz == 0 and cx == 28 and cy == 27:
            neighbors.append((28, 26, 1, 'Up'))
        elif cz == 1 and cx == 28 and cy == 26:
            neighbors.append((28, 27, 0, 'Down'))

    for dx, dy, btn in moves:
        nx, ny = cx + dx, cy + dy
        if nx < 0 or ny < 0:
            continue

        if map_id == '0_219': # West (Area 3)
            if nx >= 30 or ny >= 24: continue
            if cz == 0:
                if is_plateau_tile(nx, ny, map_id): continue
                if nx == 24 and ny <= 13: continue
                if ny == 13 and nx <= 14: continue
                if nx == 9 and 10 <= ny <= 13: continue
                if nx == 10 and ny == 11: continue
                if nx == 14 and 12 <= ny <= 15: continue
                if ny == 17 and 17 <= nx <= 23: continue
                if nx == 23 and 14 <= ny <= 17: continue
                if nx == 18 and 20 <= ny <= 23: continue
                if ny == 19 and 8 <= nx <= 17: continue
                neighbors.append((nx, ny, 0, btn))
            elif cz == 1:
                if not is_plateau_tile(nx, ny, map_id): continue
                if ny == 5 and 11 <= nx <= 16: continue
                if nx == 18 and ny == 17: continue
                if nx == 17 and 6 <= ny <= 13: continue
                neighbors.append((nx, ny, 1, btn))

        elif map_id == '0_217': # East (Area 1)
            if nx >= 30 or ny >= 25: continue
            if cz == 0:
                if is_plateau_tile(nx, ny, map_id): continue
                if ny == 7 and nx in (10, 11, 13, 14, 15, 16, 18, 19): continue
                if ny in (8, 9) and nx in (14, 15): continue
                if (13 <= nx <= 19) and ny in (10, 11): continue
                if ny == 12 and nx in (16, 17): continue
                if (5 <= nx <= 10) and (22 <= ny <= 23): continue
                if (16 <= nx <= 19) and (16 <= ny <= 17): continue
                if ny == 20 and nx <= 5: continue
                if ny == 25 and nx <= 5: continue
                if nx == 19 and (4 <= ny <= 7): continue
                if ny == 3 and (1 <= nx <= 5): continue
                if ny == 6 and nx <= 10: continue
                if nx == 6 and (18 <= ny <= 23): continue
                if nx == 16 and (22 <= ny <= 23): continue
                if (5 <= nx <= 19) and ny == 23: continue
                if ny == 21 and nx not in (9, 12, 20): continue
                if nx == 0 and (6 <= ny <= 24): continue
                neighbors.append((nx, ny, 0, btn))
            elif cz == 1:
                if not is_plateau_tile(nx, ny, map_id): continue
                neighbors.append((nx, ny, 1, btn))

        elif map_id == '0_218': # North (Area 2)
            if nx >= 40 or ny >= 36: continue
            if cz == 0:
                if is_plateau_tile(nx, ny, map_id): continue
                if (8 <= nx <= 11) and (10 <= ny <= 13): continue
                if (4 <= nx <= 7) and (14 <= ny <= 18): continue
                if ny == 34 and (10 <= nx <= 19): continue
                if ny == 33 and nx == 19: continue
                neighbors.append((nx, ny, 0, btn))
            elif cz == 1:
                if not is_plateau_tile(nx, ny, map_id): continue
                neighbors.append((nx, ny, 1, btn))

        elif map_id == '0_220': # Center (Area 0)
            if nx >= 30 or ny >= 26: continue
            if cz == 0:
                if (8 <= nx <= 21) and (8 <= ny <= 13): continue
                if (15 <= ny <= 16) and (0 <= nx <= 17): continue
                if ny == 9 and (22 <= nx <= 27): continue
                if (13 <= nx <= 14) and ny == 22: continue
                if nx == 15 and ny == 24: continue
                if ny == 25 and (nx <= 13 or nx >= 16): continue
                if ny == 24 and (nx <= 13 or nx >= 16): continue
                neighbors.append((nx, ny, 0, btn))

    return neighbors

queue = [[(start_x, start_y, start_z), []]]
visited = set([(start_x, start_y, start_z)])
path = None

while queue:
    curr, btns = queue.pop(0)
    if curr == (target_x, target_y, target_z):
        path = btns
        break
    for nx, ny, nz, btn in get_neighbors(*curr):
        if (nx, ny, nz) not in visited:
            visited.add((nx, ny, nz))
            queue.append(((nx, ny, nz), btns + [btn]))

if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
